import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.Bbwa0s72.js";const m=JSON.parse('{"title":"Form Proposal: KeyValueStore","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/key-value-store.md","filePath":"proposals/key-value-store.md"}'),n={name:"proposals/key-value-store.md"};function s(i,e,c,d,l,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="form-proposal-keyvaluestore" tabindex="-1">Form Proposal: KeyValueStore <a class="header-anchor" href="#form-proposal-keyvaluestore" aria-label="Permalink to &quot;Form Proposal: KeyValueStore&quot;">​</a></h1><p>Status: active Proposal; intended first v1alpha2 release <code>0.1.0</code>. A local candidate package exists under <code>forms/candidates/v1alpha2/</code>, but no released FormRef or public release identity exists yet.</p><h2 id="need-and-boundary" tabindex="-1">Need and boundary <a class="header-anchor" href="#need-and-boundary" aria-label="Permalink to &quot;Need and boundary&quot;">​</a></h2><p>The candidate Form describes a namespaced key-value store. It owns namespace lifecycle, narrow consistency/capability intent, and a <code>keyvalue.store@1</code> Interface. Backend engine, placement, capacity, credentials, replication, endpoint, and price remain host decisions.</p><h2 id="substrate-neutrality-review" tabindex="-1">Substrate-neutrality review <a class="header-anchor" href="#substrate-neutrality-review" aria-label="Permalink to &quot;Substrate-neutrality review&quot;">​</a></h2><p>Consistency and default expiry are consumer-observable data semantics across an edge KV, a database-backed namespace, or an embedded distributed store. Region, cache tier, replication factor, namespace/account binding, operation limits, and endpoint compatibility remain host/profile concerns.</p><h2 id="lifecycle-and-security-risks" tabindex="-1">Lifecycle and security risks <a class="header-anchor" href="#lifecycle-and-security-risks" aria-label="Permalink to &quot;Lifecycle and security risks&quot;">​</a></h2><p>Incompatible consistency or namespace changes can require copy-and-replace. Delete can destroy all keys. Import requires exact namespace ownership and capability evidence. Values, access tokens, and credential material never enter portable state.</p><h2 id="prior-art-and-gap" tabindex="-1">Prior art and gap <a class="header-anchor" href="#prior-art-and-gap" aria-label="Permalink to &quot;Prior art and gap&quot;">​</a></h2><p>OCCI generic Resource/Link, TOSCA capability relationships, managed KV operators/Crossplane resources, and Terraform Cloudflare KV/cache resources are applicable; CIMI has no focused KV contract. The gap is a minimal KV namespace and Interface without pretending provider consistency models are identical.</p>',10)])])}const y=a(n,[["render",s]]);export{m as __pageData,y as default};
